const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < input.length && input[offset] <= 32) {
            offset++;
        }
        if (offset >= input.length) return null;
        let sign = 1;
        if (input[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }
        let res = 0;
        while (offset < input.length && input[offset] >= 48 && input[offset] <= 57) {
            res = res * 10 + (input[offset] - 48);
            offset++;
        }
        return res * sign;
    }

    const xi = nextInt();
    if (xi === null) return;
    const yi = nextInt();
    const xf = nextInt();
    const yf = nextInt();

    const n = nextInt();

    const totalNodes = n + 2;
    const x1 = new Int32Array(totalNodes);
    const x2 = new Int32Array(totalNodes);
    const y1 = new Int32Array(totalNodes);
    const y2 = new Int32Array(totalNodes);

    // Node 0: Start point
    x1[0] = xi;
    x2[0] = xi;
    y1[0] = yi;
    y2[0] = yi;

    // Node 1: Target point
    x1[1] = xf;
    x2[1] = xf;
    y1[1] = yf;
    y2[1] = yf;

    for (let i = 0; i < n; i++) {
        let rx1 = nextInt();
        let ry1 = nextInt();
        let rx2 = nextInt();
        let ry2 = nextInt();

        if (rx1 > rx2) {
            const tmp = rx1;
            rx1 = rx2;
            rx2 = tmp;
        }
        if (ry1 > ry2) {
            const tmp = ry1;
            ry1 = ry2;
            ry2 = tmp;
        }

        const idx = i + 2;
        x1[idx] = rx1;
        x2[idx] = rx2;
        y1[idx] = ry1;
        y2[idx] = ry2;
    }

    function dist(u, v) {
        let dx = 0;
        if (x1[u] > x2[v]) {
            dx = x1[u] - x2[v];
        } else if (x1[v] > x2[u]) {
            dx = x1[v] - x2[u];
        }

        let dy = 0;
        if (y1[u] > y2[v]) {
            dy = y1[u] - y2[v];
        } else if (y1[v] > y2[u]) {
            dy = y1[v] - y2[u];
        }

        return dx + dy;
    }

    const d = new Float64Array(totalNodes);
    d.fill(Infinity);
    const visited = new Uint8Array(totalNodes);

    d[0] = 0;

    for (let step = 0; step < totalNodes; step++) {
        let u = -1;
        let minDist = Infinity;

        for (let i = 0; i < totalNodes; i++) {
            if (!visited[i] && d[i] < minDist) {
                minDist = d[i];
                u = i;
            }
        }

        if (u === -1 || u === 1) {
            break;
        }

        visited[u] = 1;

        for (let v = 0; v < totalNodes; v++) {
            if (!visited[v]) {
                const weight = dist(u, v);
                if (d[u] + weight < d[v]) {
                    d[v] = d[u] + weight;
                }
            }
        }
    }

    console.log(d[1]);
}

